import { contextBridge, ipcRenderer } from 'electron'
import { isNoteList, NOTES_CHANNELS, type NotesBridge } from '@shared/notes'

const notes: NotesBridge = {
  async list() {
    const answer: unknown = await ipcRenderer.invoke(NOTES_CHANNELS.list)
    return isNoteList(answer) ? answer : []
  }
}

contextBridge.exposeInMainWorld('notes', notes)

