import { Suspense, use } from 'react'
import type { Note } from '@shared/notes'
import { countLabel } from '../domain/count'

const loaded = window.notes.list()

function Rows({ notes }: { notes: Promise<Note[]> }): React.JSX.Element {
  const list = use(notes)
  return (
    <section>
      <p>{countLabel(list.length)}</p>
      <ul>
        {list.map((note) => (
          <li key={note.id}>{note.text}</li>
        ))}
      </ul>
    </section>
  )
}

export function NoteList(): React.JSX.Element {
  return (
    <Suspense fallback={<p>Loading notes</p>}>
      <Rows notes={loaded} />
    </Suspense>
  )
}

